        "passage": "民國109年間,我國中央政府開放進口美國含有萊克多巴胺(萊劑)的豬肉。為管制萊劑殘留標準,中央先修訂食安法,再依照新條文公告「動物用藥殘留標準」,另規定含有豬肉及豬可食部位的原料,須標示原產地,讓國人選購時清楚產地來源。針對開放萊豬的政策,部分地方政府採取因應措施,例如:某市在食品安全衛生管理自治條例規定,豬肉及其相關產製品不得檢出萊劑;經檢出者,依其含量處以不同罰鍰,並得按次處罰。但行政院於同年底,函告該市政府上述自治條例相關內容無效。",
