        "passage": "1918年爆發的「西班牙流感」,曾造成全球數千萬人死亡。該疫情早在1918年春天,即在大戰的西線戰場出現,只是當時許多國家正值戰事,進行媒體審查,隱匿本國及軍隊的疫情,但西班牙因未參戰也沒有媒體審查限制當地疫情報導,在其他國家大量轉載西班牙的新聞下,導致世人誤以為該次流感是從西班牙開始。後來研究發現,流感第一個病例於1918年春天出現在美國堪薩斯城的軍營,隨後因美國參戰而傳播至歐陸。表3是1918年底美國三個都市的流感死亡人數。\n表3:\n| 都市 | 死亡人數(人) |\n| 堪薩斯城 | 382 |\n| 洛杉磯 | 1546 |\n| 費城 | 7024 |",
