        "passage": "2022年2月俄羅斯軍隊入侵烏克蘭。俄國總統普丁以本國的立場,主張烏克蘭原本就屬於俄國,因此他要拿回烏克蘭。但許多學者表示,普丁的說法並不符合史實。\n當烏克蘭軍隊收復曾遭俄軍占領的布查鎮(Bucha)後,隨其進入鎮內的英、美國際媒體立即報導了俄軍占領時曾屠殺平民的新聞,呈現平民屍體倒臥路旁的照片、影片,並訪談了劫後餘生的當地居民,作為報導的一部分。俄羅斯的國營媒體立即全盤否認,宣稱俄軍從未對平民攻擊,並指控烏軍偽造平民死於路旁的影像。其後英、美媒體指出,這些影像在俄軍占領期間即已在社群網站上張貼過,且衛星影像也顯示相同時間、位置的平民屍體。",
