        "passage": "1988年,臺灣仍處於《動員戡亂時期臨時條款》下的緊急狀態,人民基本權利受到嚴格限制。而各中央民意機構仍有過半以上代表不必改選,長年由1940年代大陸各省市選出者擔任,與臺灣社會脫節。\n為平衡對外貿易逆差,當時的行政部門擬開放國外農產品進口,但有農民認為此舉嚴重衝擊農民生計,因而在相關提案送立法院審議時,部分農民集結臺北抗議,這在當時屬於體制外的抗爭。抗議過程原本平和,途中卻發生警民推擠、逐漸失序,當警察提高鎮壓強度,部分群眾也予以還擊,在混亂與衝突中民眾遭逮捕約90餘人。\n其後,檢方以「預藏器具進行暴力行動」等罪名起訴被捕群眾,即便有現場紀錄片拍攝者、學者、人權律師等舉出事證澄清,認為不存在檢方所稱「預謀」,但未獲採信,法院最後判決其中19人有罪。定罪的一個重要關鍵,即為檢方舉證其中有人預謀運送石塊、鐵棍以攻擊警方。\n至2022年,上述案件,被「促進轉型正義委員會」認定為冤案,屬於威權體制下「司法不法」的受害者而獲得平反。",
