        "explanation": "資料甲、乙對「穆斯林(伊斯蘭)統治是否導致印度文明僵化落後」提出截然相反的歷史解釋——甲認為伊斯蘭入侵使印度文明僵化,乙則認為穆斯林統治(蒙兀兒帝國)反而帶來商業、文化、社會的進步發展;這種對同一段跨文化統治歷史、其發展機會評價不同的比較,最適合用來探討「文化異同與其發展機會」的主題,而非全球化經濟史、獨立運動或區域互賴等其他主題。(113學測社會第42題,官方答案B)"
