        "passage": "某部小說寫道:某彭姓長工偕同妻兒及童養媳燈妹,前往番仔林墾殖。燈妹原是棄嬰,被收養後再轉賣給彭家,預備長大後和彭家兒子拜堂為夫妻。番仔林是原住民族生活空間,漢人進入採集山產或墾殖常遭原住民激烈抵抗。彭家入墾前三年,政府在該地區設撫墾區、番學堂,並布置隘寮僱請隘勇守衛,但仍時有原、漢衝突。彭家進入番仔林後,一家大小在草寮住處周圍的緩坡地伐除茅草和雜木,除林後的緩坡地,首先撿除較大石塊、栽種甘藷,然後在部分山泉較充足的地方,逐步將「甘藷田剷平,築成梯田,引水灌溉種植水稻。」漸漸在番仔林建立起新的家園。",
