        "passage": "土耳其領土橫跨歐、亞兩大陸,被稱為文明的十字路口,五千年來歷經波斯、希臘、羅馬、拜占庭、鄂圖曼和土耳其共和國等的治理。由於地理位置與歷史發展的影響,土耳其在區域歸屬上,始終擺盪於「西方(歐洲)」與「東方(西亞)」之間;雖然早於1952年即加入北大西洋公約組織,但近年來幾經爭取,迄今仍未成為歐盟的正式會員國。2017年土耳其通過修憲公投,將憲政體制由議會內閣制改為總統制,總統由普選產生且擁有更大行政權,由總統組成政府並任免各部會首長。\n俄烏戰爭期間,多國對俄羅斯實施經濟制裁,禁止俄國石油、天然氣等能源的進口。圖6是俄羅斯、烏克蘭位置圖。土耳其國內的反對黨,亦提出封鎖俄羅斯交通線的制裁方案,但執政黨基於該國能源高度依賴俄羅斯,表明不會加入制裁俄羅斯的行列。",
