        "origNo": 53,
        "sourceYear": 113,
        "question": "寫出文中該國(土耳其)反對黨若要阻絕俄羅斯海運，從地理位置面向提出制裁方案的主要做法（1分），且說明該做法將使俄羅斯對外交通所帶來的具體影響。【須明確寫出具體受影響的海域名稱】（2分）\n(說明:官方原題另要求先在答題卷地圖上以2B鉛筆標示出土耳其位置,1分,但此為地圖標示/繪圖作答,系統無法呈現,故僅保留以下文字作答部分,總分以3分計。)",
        "explanation": "【滿分參考答案】\n主要做法:土國若將(歐亞大陸之間的)海峽封鎖。\n對俄羅斯影響:將使俄國船隻無法從黑海出入地中海。\n\n【評分原則】\n【主要做法】等級1(完全給分):正確作答「土國若將(歐亞大陸之間的)海峽封鎖」,或具體寫出「博斯普魯斯、達達尼爾海峽封鎖」,或「土國若將歐亞大陸之間的航道封鎖」。等級0(不給分):作答錯誤的海峽名稱;或作答「封鎖俄羅斯交通線」等未具體指明海峽的敘述。\n【對俄羅斯影響】等級1(完全給分):正確作答「將使俄國船隻無法從黑海出入地中海」。等級0(不給分):僅作答「無法從黑海出入」或僅作答「無法從地中海出入」(未完整寫出黑海與地中海兩端)。\n\n(土耳其扼守博斯普魯斯海峽與達達尼爾海峽,是黑海通往地中海的唯一水道;若土耳其(反對黨主張)將此海峽封鎖,將使俄羅斯船隻無法經由黑海出入地中海,對俄羅斯的海上對外交通造成重大影響,這也是為何土耳其執政黨考量本國能源高度依賴俄羅斯而不願配合封鎖。)\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形;地圖標示部分請自行參照地圖確認土耳其位置,系統不呈現此部分。)"
