        "explanation": "【滿分參考答案】(以下三種答案皆為官方認可的滿分寫法之一)\n學校設立的都市:臺北\n方案一:概念(勾選)聚落系統。考量依據:因為該都市在臺灣聚落系統中是最高等級的都市,所以第一所女子中等學校會先設在該都市。\n方案二:概念(勾選)市場區域。考量依據:因為該都市是臺灣中地等級最高的都市,擁有涵蓋全臺的市場區域,所以第一所女子中等學校會先設在該都市。\n方案三:概念(勾選)都市機能。考量依據:因為該都市是臺灣政治(文教)機能層級最高的行政中心,所以第一所女子中等學校會先設在該都市。\n\n【評分原則】\n【學校設立的都市】等級1(完全給分):正確作答「臺北」。等級0(不給分):未正確作答。\n【概念/考量依據】(勾選聚落系統、市場區域、都市機能三者之一,並搭配正確理由,皆可得滿分,三者不可複選)等級2(完全給分):勾選一個概念,且正確、完整說明對應該概念的考量依據(見上述方案一/二/三對應文字)。等級1(部分給分):勾選一個概念,但考量依據的說明不夠精準完整(如僅寫「等級較高」而非「最高」)。等級0(不給分):勾選一個概念但未說明或說明錯誤;或未勾選概念僅說明依據;或勾選兩個以上概念。\n\n(第一所女子中等學校(國語學校第一附屬學校女子分校,1897年)設於臺北,臺北做為當時全臺聚落等級最高、政治文教機能最完整、市場區域涵蓋全臺的核心都市,自然是總督府優先設置指標性新式學校的地點;由於三個地理概念(聚落系統、市場區域、都市機能)在此题都能自圓其說並各自對應官方認可的正確理由,只要勾選其中一項並搭配正確理由即可得滿分,因此本題以 type:written 呈現,提供讀者練習三種角度的完整寫法,而非強制系統自動判定某一項勾選才算正確。)\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
