        "passage": "十九世紀,華人開始大規模移民美國,先後從事開挖金礦、修建鐵路等勞力工作。當時載運華工橫渡太平洋的輪船公司,為了提高利潤而超載,船艙極端擁擠,華工在漫長旅途中,常受非人待遇而死亡,甚至有高達64%的死亡率紀錄。即使如此,移民美國的華人仍持續增加。\n在鐵路修建告一段落時,又值美國政府立法廢除某項制度後,出現低階勞動力不足的現象,各地華人移工開始進入農、漁、工勞動市場,而白人擔心工作被奪取,薪資被壓抑,針對華人的種族暴力時有所聞。更多的華人陸續聚居到不同的市區,形成各地的「唐人街」族群經濟聚落,其職業與行業特色以經營小生意為主,市場規模小但可互助兼自保。他們赴美時常將妻子留在家中撫養子女、照顧公婆;加上在海外謀生不易,妻子即使來美也不太可能有工作機會。因此,早期唐人街的男性華人,大多是過著類似「光棍」(單身)的生活。\n1873年後美國經濟蕭條,對華人移民的歧視更形加劇。在工會遊說及各州議會的強力支持下,美國國會在1882年完成立法、由總統簽署通過《排華法案》,對華人移民入境與取得美國籍都設下嚴格限制,這是美國政府通過的唯一針對移民國籍所設定的歧視性法案。",
