        "question": "題文中，美國出現低階勞動力不足的現象，和該國立法廢除哪項制度有關？（2分）此外，早期移民美國的華人，大多過著類似「光棍」（單身）生活的因素為何？（2分）",
        "explanation": "【滿分參考答案】\n廢除的制度:奴隸制度\n過類似光棍生活的因素:將妻子留在家中照顧老小(或:海外謀生不易,即使妻子赴美也缺乏工作機會)。\n\n【評分原則】等級2(完全給分):正確寫出制度名稱,並能完整說明因素。等級1(部分給分):正確寫出制度名稱,但對因素的說明不完整或錯誤;或未寫出制度名稱,而因素的說明正確或不完整。等級0(不給分):制度名稱及因素的說明錯誤;或未作答。\n\n(美國於南北戰爭後(1865年)立法廢除奴隸制度,原本由黑奴承擔的低階勞動力頓時短缺,促使華工大量進入農、漁、工等勞動市場填補空缺;而早期赴美華人男性大多將妻子留在家鄉照顧子女、侍奉公婆,加上海外謀生不易、妻子即使隨行赴美也難有工作機會,種種因素使得早期唐人街的男性華人大多過著類似「光棍」的單身生活。)\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
