        "passage": "朱一貴事件後,隔年(1722)某官員於〈諭閩粵民人〉的文告中提及:「以後不許再分黨羽,再尋仇怨,各釋前怨,共敦新好。」1764年《重修鳳山縣志》收錄這份文告時,不僅將篇名改為〈閩粵相仇論〉,內容也改成:「以後不許再分黨羽,再尋仇釁。漳、泉、海豐(廣東惠州府)、三陽(廣東潮州府)之人經過莊,客民經過泉、村落,宜各息前怨,共敦新好。」請問:",
        "origNo": 29,
