        "passage": "新加坡的發展不僅與英國人有關,也與當地最大族群華人的關係密切。十九世紀中興建的蘇伊士運河,打通了西歐與東亞的新航路,促使歐洲人在東南亞大力發展熱帶栽培業,故需要許多人手進行種植、管理、初步加工和產品運輸等,提供了新加坡發達的基礎,也使當地華人人口迅速上升。新加坡不僅是英國海峽殖民地的行政首府,也是東南亞熱帶作物銷往歐洲的集散中心。圖3是歐、亞、非三洲的形勢簡圖,甲—丁是世界上重要的海峽。\n(圖3示意:歐亞非世界地圖上以箭頭標示四個海峽——甲位於西北非與伊比利半島之間的狹窄海口;乙位於紅海南端、阿拉伯半島西南端與非洲之角之間;丙位於阿拉伯半島與伊朗之間、波斯灣出口處;丁位於東南亞中南半島與蘇門答臘島之間。)請問:",
