        "passage": "1920年代臺灣民眾積極參與政治抗爭活動,其中以在日臺灣留學生組成的「新民會」等發起、前後15次的「臺灣議會設置請願運動」為著。何以民眾會採用請願方式?因為統治者不願將日本本土的行政救濟制度施行於臺灣,人民無從透過行政訴訟對抗政府,達成改革訴求,故選擇體制內許可、效力較弱的請願權。\n在第3次請願運動期間,參與民眾在臺倡議成立「臺灣議會期成同盟會」,卻被警察以違反《治安警察法》禁止此類結社為由制止。參與者不服警察禁令又投訴無門,全島更有百餘位遭到逮捕、起訴。但一審法院判決被告全數無罪,導致檢察官不服上訴,直至二審,才改判徒刑或罰金。\n經歷此事件,論者認為總督府法院對檢方起訴內容不會照單全收,仍有依法審判空間,反而激起當時臺灣民眾的政治參與熱潮。請問:",
