        "passage": "閩南語歌曲〈青蚵嫂〉描述養蚵、賣蚵的婦女心聲,歌詞寫道:「別人的阿君仔(丈夫)是住『西洋樓』,阮的阿君仔是睏『土跤兜』(地板),運命好歹是無計較,若有認真是會出頭。」過往人們認為這段歌詞一方面反映出牡蠣產業風險高,收入不穩定,另方面也透露出傳統女性的命運取決於所嫁對象。但晚近有學者訪談當年青蚵嫂,發現她們既覺得命運寄託於婚姻,同時也肯定自己剝蚵本事在、多少改善生活,學者主張這意味女性能在傳統體制下發揮主體性、創造希望。請問:",
