        "passage": "二次世界大戰後,美蘇兩強對峙,夾在中間的歐洲思考如何走出自己的路。1950年,一幅以「放大鏡下的歐洲:第三力量」為題的政治漫畫(圖4),將歐洲各國畫成小孩子,被兩位大人以放大鏡檢視,有些小孩子被壓制在一位大人的膝蓋下方。\n1952年,德、法、義、荷、盧、比等六國,成立「歐洲煤鋼共同體」,其想法來自法國提出西歐各國將重要工業資源共同管理的計畫,規定成員國間毋須繳納關稅而直接取得煤和鋼的生產原料。1958年,六國成立「歐洲經濟共同體」與「歐洲議會」;1967年,六國依條約整合成「歐洲共同體」;1993年,「歐洲共同體」正式更名為「歐洲聯盟」(歐盟)。\n2004年起,東歐多國才陸續加入歐盟;英國則因國內諸多問題,而於2016年公投決定退出,並就移民、國際貿易、跨國金融等與歐盟進行談判。請問:",
