        "passage": "人工智慧(簡稱AI)看似能與人們溝通、提供各種回答,但其運作仰賴大量素材供其學習。若素材本身就有偏頗,AI的答案就可能強化這些偏頗。例如,因既有科學家圖片幾乎都是白人男性,當AI收到「畫出科學家」指令時,就極可能畫出白人男性圖像。\n為防止AI誤導人們以為白人男性才會成為科學家,曾有不同族裔與性別的科學家串連,只要發現媒體報導他們的研究,卻搭配AI生成的不相關白人男性示意圖,就向媒體抗議要求更換成正確族群或性別的圖片。參與抗議的科學家甲主張:抗議不只為了自身,也為了讓有科學才能的邊緣群體青年世代,不會因媒體偏頗而懷疑自己、放棄科學才能,所以抗議可促進青年世代自我實現。\n學者乙指出AI的偏頗使某個國家的人民常被視為潛在恐怖分子,以致參加國際活動時受到不公平的對待,甚至失去話語權。\n學者丙認為上述偏頗也會影響司法公正,如法院或行政機關使用AI評估受刑人再犯風險,以做出假釋決定,結果顯示AI會認定有色人種有更高再犯風險。由於AI的訓練資料不公開,外界無法監督,且其演算邏輯不易理解,故難以對評估結果提出質疑。\n學者丁則提出AI的耗能問題:AI伺服器的耗電量較傳統高出20倍,且需大量水資源降溫機房;根據研究,與ChatGPT對話一次需消耗約一罐寶特瓶的水。從社會福祉的角度,應讓AI產品反映其潛在成本。請問:",
