        "passage": "北美的原住民過往曾遭遇北美殖民者的屠殺和迫害。例如:英國殖民者曾與原住民佩柯特人簽訂條約,稱呼部落酋長為國王;雙方交戰時遵循國與國交戰規則,不得攻擊對方平民。後來英軍卻突然攻擊佩柯特部落,屠殺眾多平民,後續又有不少平民被賣為奴隸,佩柯特人從此無法再起。由於當時歐洲國家掃蕩亂民者時被允許屠殺平民,英軍看來推翻了過去和佩柯特人的交戰規則,將佩柯特人視為叛亂者。\n晚近,美國某大學的原住民族學生積極在校園內建立原住民族社群、舉辦原住民族週活動。一位參與的原住民學生表示:我們在校園中非常辛苦,主流社會否定我們的存在、看不見我們。我們需要一個能看見彼此、相互共鳴的原住民社群,一起打造美好未來。請問:",
