        "passage": "臺灣的土地產權歷經演變,逐步形成今日制度。清代臺灣的大、小租制是一種土地的雙重所有制:大、小租可分開來交易,小租的買賣不需要大租戶同意,反之亦然。大、小租制最大的問題就是土地利益狀態不明確,容易產生糾紛。劉銘傳曾想廢除只在遠方收租、無法決定土地用途的大租戶,但無疾而終。後基於政府土地管理和稅收考量,改以「減四留六」政策,將田賦改由在地小租戶繳交,自此小租戶變成官府認定的業主。\n「減四留六」政策的推出,過去都認為是劉氏屈服於大租戶反抗而妥協的結果,但近年研究指出,這其實是日治初期總督府為順利廢除大租權而提出的說詞。\n日治初期為解決一田多主的現象,乃實施整理,賦予這些土地關係法律上的權利,由總督府買下所有的大租權,且不再繼續向小租戶收取大租。為了消滅大租權,改造為「一田一主」,總督府並開始推動土地調查,以訂定明確的大租權補償標準及改訂地租率,此項措施解決了土地產權不明確的問題。請問:",
