        "explanation": "【滿分參考答案】\n該政策最主要的影響(20字內):更可掌握田賦稅收。或:使土地所有權更明確。\n該說詞有助於順利廢除大租權的原因(30字內):延續前朝政策,以強化廢除大租(戶)的正當性。或:污名化大租戶,以強化廢除大租(戶)的正當性。\n\n【評分原則】\n等級2(完全給分):準確寫出政策的影響,並能完整說明該說詞有助於廢除大租權的原因。\n等級1(部分給分):1-1準確寫出政策的影響;原因的說明不完整或錯誤。1-2未完整寫出政策的影響;原因的說明正確、不完整或錯誤。1-3政策的影響作答錯誤;原因的說明正確或不完整。\n等級0(不給分):0-1政策的影響及原因的說明書寫錯誤。0-2未作答。\n\n(「減四留六」使田賦直接改由在地小租戶繳交,官府得以更直接掌握田賦稅收來源、確立土地所有權歸屬更加明確,便於統治管理;而總督府將此政策詮釋為「劉氏屈服於大租戶反抗而妥協」的既有清代政策延續,而非日本人自己新創的措施,藉此塑造廢除大租權只是「延續前朝既有方向、更進一步落實」的正當性形象(或藉此說詞將大租戶塑造為需要被壓制改革的一方),有助於降低廢除大租權時大租戶及社會的反彈阻力,使政策得以順利推行。)\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
