        "passage": "番茄為全球最重要的蔬果之一,其加工品「番茄糊」也成為需求甚殷的產品。遺傳學家成功透過基因改造,培育可長途運輸且更便於製成濃縮番茄糊的「加工用番茄」,使番茄種植及生產番茄糊的地點不再受限,可創造更大利潤。\n一名記者在那不勒斯的老牌番茄糊工廠,發現其他廠牌的桶裝番茄糊,其生產標籤上寫著:「中國製造」。該工廠不再以生產番茄糊為主,而是將番茄糊調整風味後,分裝成小容量的罐裝產品出售。經過長時間的採訪,他完成番茄糊產業加工途徑的調查,圖6為其中一條全球番茄糊加工業的途徑。\n(圖6示意:歐亞非世界地圖,圖例標示「●主要生產工廠」集中於中國,「■主要分裝工廠」分布於中國與西非沿岸,「➤番茄糊產品出口動線」以粗箭頭呈現由中國指向南歐義大利那不勒斯,另有較細箭頭指向西非等地。)請問:",
