        "explanation": "【滿分參考答案】\n對價格與數量的影響(10字內):價格上升、消費量減少(或 產量增加)。\n生產者剩餘的變化(5字內):上升。\n\n【評分原則】\n等級2(完全給分):正確回答A、B兩項——A.左欄完整寫出「價格上升」、「消費量減少(或 產量增加)」二項要件(2分);B.右欄寫出「上升」(1分)。\n等級1(部分給分):2分,A正確,B未作答或錯誤;1分,A僅正確回答一項要件,無論B是否正確。\n等級0(不給分):A完全錯誤或未作答(無論B是否正確)。\n\n(美國農畜產品原本只在國內市場銷售,開放對外貿易、大量出口後,國外需求加入國內市場,使美國農畜市場的均衡數量(產量)增加、均衡價格也隨之上升(因整體市場需求擴大);對美國國內生產者而言,以更高的價格銷售更多數量的產品,其生產者剩餘(生產者從交易中獲得的利益)因而上升,這正是貿易開放後出口國生產者受益的典型結果。)\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
