        "passage": "唐朝雖建都於黃河中游渭河流域的關中平原,但常有天然災害發生,中央政府財賦主要來自黃河下游地區。唐初以來,官府為因應災害的衝擊,在各地建立糧倉,以調節糧價和儲備救災。同時官府懷抱愛民如子之心,提供施粥救飢、給藥治病等多項福利措施,亦有民間力量加入施恩救苦。\n安史亂後,原本的財政稅賦來源受藩鎮割據影響而被切斷,且連年戰亂和政治敗壞導致北方人口大量外移,農業生產難以復原,糧倉制度也無法維持。此時,中央政府愈加仰賴由大運河運來的糧食,以供養京師和軍隊,而江南的開發,也帶給中央政府穩定的稅收。請問:",
