        "explanation": "檢察官乙在「偵訊期間」尚未經法院判決有罪前,就已表示「一定要將甲繩之以法」,預先認定甲有罪,這正違反刑事訴訟「無罪推定原則」(被告在判決確定前應推定為無罪)(選項C);甲拒絕在無律師陪同下受偵訊是正當行使緘默權與辯護權,並非現行犯就應被拒絕請律師(選項A錯誤);甲若自白是甲主動放棄不自證己罪的權利,而非「牴觸」該原則(選項B邏輯有誤);乙在「審判時」強調甲拒絕自白應從重量刑,是不當侵害緘默權、影響公正審判,而非「偵查不公開」(那是指偵查中案件內容不得公開,與此處情境不符,選項D錯誤)。(115學測社會第4題,官方答案C)"
