        "question": "十六世紀末期,駐菲律賓的西班牙總督向國王報告,在菲律賓和華人貿易有害而無益,因為華人運來了大量棉布、粗糙廉價的絹疋,還有生絲或紡絲等在此貿易。而最令人憂慮的是它們還超過西班牙運來的輸入量,這將會導致格拉那達、瓦倫西亞等地繳納給王室的稅收減少。依據題文,總督最擔憂的是:",
        "options": [
          "菲律賓當地紡織品產量降低,人民將缺乏布料",
          "華人已逐步取得西班牙貿易代理權並壟斷貿易",
          "若是進口中國大量廉價貨物,本土產業將毀滅",
          "西班牙出口至菲律賓的紡織品數量將日益減少"
        ],
        "answer": 3,
        "explanation": "總督報告的核心憂慮是華人運來的棉布、絲織品等「超過西班牙運來的輸入量」,將導致西班牙本土(格拉那達、瓦倫西亞)紡織業繳納給王室的稅收減少,顯示他最擔心的是西班牙本國紡織品輸往菲律賓的貿易數量會被中國廉價商品排擠而日益減少(選項D);題文並未提及菲律賓「本地」紡織品產量或人民布料短缺(選項A)、華人取得代理權壟斷貿易的說法(選項B),而選項C雖與稅收減少有關聯,但題文明確聚焦在「王室稅收」的減少,更精確對應的是西班牙紡織品出口量下降這一具體現象(選項D)。(115學測社會第14題,官方答案D)"
