        "origNo": 20,
        "sourceYear": 115,
        "question": "某生玩一款手機遊戲,其中一個關卡需要先利用射程200公尺的狙擊槍來癱瘓某座碉堡頂端的探照燈,而且若走入該碉堡半徑40公尺的範圍內,則會被碉堡內的士兵發現並遭到反擊。圖5是該關卡的地圖,每個網格為10公尺的正方形,網格內的數值代表高度,黑色網格為碉堡所在位置,灰色網格為射擊地點候選位置。若要成功過關,該生選擇下列哪個網格作為射擊地點最為理想?\n(圖5示意:7欄×7列的高度數值網格,每格邊長10公尺,由上而下、由左而右各列數值依序為:\n第1列:55、80(乙,灰色)、90、80、80、75、85(黑色,碉堡);\n第2列:35、65、65、65、60、70、50;\n第3列:50、65、75、60、65、65、70;\n第4列:65、70、90、60、70、70、80(丁,灰色);\n第5列:70、75、90、60、70、95、65;\n第6列:80(甲,灰色)、75、85、70、65、55、70;\n第7列:20、70、70、80(丙,灰色)、45、55、45。\n碉堡位於第1列最右格,高度85公尺。)",
