        "explanation": "法治國原則下的「比例原則」要求國家限制人民權益(如加重罰鍰)的手段,須與所欲保障的法益(此處為交通安全與順暢通行等公共利益)之間維持合理的衡平關係,故市政府修法調整罰鍰金額時,應「參酌罰鍰與保障法益的衡量,適當調整罰鍰金額」(選項C)才符合法治國原則;調高罰鍰金額本身並不當然違反信賴保護原則(該原則保障的是人民對既有法秩序的合理信賴,而非禁止任何法規修正,選項A過度延伸);「最能有效遏止違停」的效果性判斷並非法治國原則(比例原則、法安定性等)的核心關注點(選項B文不對題);而依違規情節輕重程度給予不同罰鍰,正是比例原則精神的展現,並不違反平等原則(選項D對平等原則的理解有誤)。(115學測社會第27題,官方答案C)"
