        "passage": "在花東一帶,有些土地原本是臺灣原住民族祖先生活的傳統領域,但在日治時期,傳統領域被政府當成是無主土地。政府除趕走原來的原住民使用者,又將其劃為糖業種植經濟區域,給予日資會社發展糖業。戰後政權轉移,政府將相關土地所有權劃歸公營的台糖公司所擁有,這使得日後在該地上耕作的原住民,雖可能是原始土地使用者,反而每年要向台糖納租,成為佃農。\n晚近為解決此一問題,原住民族委員會遂以行政命令,以價購方式將台糖買回符合前述情形的土地。再依照現有法律程序將該項土地註記為原住民保留地,且將所有權分配給相關原住民擁有。而原住民擁有之保留地,除有特別的規定之外,原則上不得轉讓或出租給不具原住民族身分者。請問:",
