        "passage": "日治初期,曾在臺北城北廓外設置「三板橋墓園」,作為日人專屬的葬儀堂、公墓、火葬區。日治後期,隨著都市發展,該墓園曾被規劃為14、15號公園預定地但無實施。1949年後,該墓園首先為自中國大陸湧入之無住屋難民搭建臨時住宅所占,之後又吸納少數外縣市勞工,處境不利群體遷入,形成跨族群與互助的違建社區。\n時至1997年,臺北市政府欲推動該地公園建造計畫,欲強拆違建並迫使住戶遷出,引發抗爭。某支持抗爭的學者指出:基於人性尊嚴考量,應依居民生活脈絡、社會關係和謀生,妥善規劃安置,而不是隨便將居民驅離或置於安養機構,要求市府暫緩拆除,這也是臺灣史上第一次的反迫遷運動。請問:",
        "origNo": 35,
