        "passage": "國共內戰後期,在中國西南地區的一部分國軍撤退至滇緬邊境的山區,建立游擊基地,被稱為「異域孤軍」。1950年代中期,政府將部分軍人與眷屬撤回臺灣,在北部某地成立眷村安置。當時選擇眷村地點的原則是:農業生產力較差、地價較便宜的邊際土地,與舊住民聚落相隔適當距離。當時部分撤回軍民因無法證明軍籍或軍眷身分,亦無法辦理戶籍而導致成為無國籍人,在就學、就業、居住與社福等方面皆陷入困境。請問:\n(圖7示意:某地土地利用簡圖,圖例包括聚落(密集三角形符號,主要分布於圖右上角一帶)、主要道路(貫穿全圖的路網粗線)、埤塘(水塘符號,散布於中央水田區)、水田與茶園(點狀、圈狀符號,分布於圖中、上部及部分坡地)、旱田與休耕地及基地(較稀疏的符號,分布於圖左側與下方邊緣、地價較低的邊際地帶)。圖上標示甲(左上方,鄰近水田與道路交會處)、乙(右上方,位於密集聚落內)、丙(中央偏右,鄰近道路且接近聚落外緣)、丁(下方邊緣地帶,鄰近旱田、休耕地與基地符號,距離聚落最遠)四個候選位置。)",
