        "question": "若要進一步研究「孤軍」在當時的處境,下列哪些是屬於證據價值高的第一手史料?\n甲、當代學者所撰寫的《孤軍歷史研究》 乙、孤軍官兵們的口述訪談記錄與回憶錄\n丙、有關「異域孤軍」的文學、影視作品 丁、該地國軍撤退、滯留決策的官方檔案\n戊、設立「異域孤軍故事館」的相關報導",
