        "passage": "從文化政策角度來看,我國曾存在國家以公權力抑制特定文化之現象。例如,1970年代,以本土語言播出的布袋戲電視節目轟動一時,卻遭禁播。禁播原因之一為政府宣稱節目充斥低俗趣味,且有違國語運動政策。而該劇主題曲也因為歌詞提及女主角「討厭交男子,歡迎女朋友」,帶有同性戀隱喻,且強調女主角喜好江湖風流,不符女性應有氣質,遭到禁播。\n針對前述現象,有學者提出,當時無論在公開場合、文學或表演藝術的領域,已出現本土語文的更普遍使用。例如在選舉期間,有候選人幾乎全程採用本土語言進行街頭演講,同時也有鄉土文學作家書寫草根人物的本土語言習慣。請問:",
