        "passage": "某高中生探究「多元文化」主題時,看到十九世紀後期一位歐洲作家到亞洲旅行時的紀錄,寫到:「某地」因為發現礦產與橡膠種植,吸引了亞洲各地人士搭乘帆船、汽船或阿拉伯式小船抵達這城市,景象驚人。一位當地船夫表示:「女王很好——我們苦力能賺到錢;而且能把錢存起來。」儘管工作辛苦,但人們不需要倚賴他人,還能保有自己的服飾、習俗與宗教。\n該生反思後認為,當時統治者只關注治安與稅收,並安排各族群只能從事特定的職業,例如白人是官員,華人從事貿易或採礦,印度人充當警察、傭兵,本地土著則為苦力與農、漁工等。統治者雖然讓他們依據各自的傳統或宗教習俗進行自治,但這不合乎當今法治國家對於族群多元的重視方式。當今法治國家政策會更重視各族群處境的不同,給予合理差別待遇以促進各族群的發展。請問:",
